    'از بخشِ «خدمات» → «اسنپِ بار» → «ثبتِ بار» را انتخاب کنید. مبدأ، مقصد، عنوانِ بار و وزن را وارد کنید. بارِ شما به رانندگانِ در مسیر نمایش داده می‌شود.': 'Bölümden "Hizmetler" → "Anlık Yükleme" → "Kaydı Yükle" seçeneğini seçin. Kalkış yerini, varış yerini, kargo unvanını ve ağırlığını girin. Yükünüz güzergah üzerindeki sürücülere gösterilecektir.',
    'از کیفِ پول → «انتقالِ امن» استفاده کنید و Earth ID گیرنده را وارد کنید. این جریان سفارشِ امانی می‌سازد تا پیش از تسویه، وضعیتِ پرداخت قابلِ پیگیری و برگشت باشد.': 'Cüzdan → "Güvenli Aktarım"ı kullanın ve alıcının Earth ID\'sini girin. Bu akış, ödeme durumunun takip edilebilmesi ve ödemeden önce iade edilebilmesi için bir güven emri oluşturur.',
