    'اکنون در سطحِ منطقه (fuzzed) روی کره دیده می‌شوید.': 'Artık dünya üzerindeki bulanık alanı görebilirsiniz.',
    'اگر بار پذیرفته شده باشد، وجهِ امانی کاملاً به شما بازمی‌گردد. پس از تحویل‌گیری دیگر لغو ممکن نیست.': 'Yükün kabul edilmesi durumunda depozito tarafınıza tamamen iade edilecektir. Teslimattan sonra iptal mümkün değildir.',
    'اگر کسی شما را به دیلیکس دعوت کرده، Earth ID او را ثبت کنید. این کار فقط یک‌بار ممکن است.': 'Birisi sizi Dilix\'a davet ederse, onun Earth ID\'sini kaydedin. Bu yalnızca bir kez mümkündür.',
