    'اینجا هنوز پستی نیست.': 'Burada henüz bir yazı yok.',
    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'Bir hesap oluşturarak doğru bilgi sağlamayı, Hizmeti yasa dışı faaliyetler için kullanmamayı ve oturum açma bilgilerinizin gizliliğini korumanın sorumluluğunu üstlenmeyi kabul edersiniz.',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'Yayın başladığında kameranız ve mikrofonunuz izleyicilere gönderilecektir. Başka bir açık oynatmanız varsa kapatılacaktır.',
    'با پذیرش، {0} تومان از کیفِ پولِ شما امانی می‌شود و بقیهٔ پیشنهادها رد می‌شوند. این کار برگشت‌پذیر نیست.': 'Kabul edildikten sonra cüzdanınıza {0} Toman yatırılacak ve geri kalan teklifler reddedilecek. Bu geri döndürülemez.',
    'با پلاک یا کد ملی، سوابق و سطحِ تخفیف را می‌آوریم.': 'Plaka veya ulusal kod ile kayıtları ve indirim seviyesini getiriyoruz.',
