    'از کیفِ پول → «انتقالِ امن» استفاده کنید و Earth ID گیرنده را وارد کنید. این جریان سفارشِ امانی می‌سازد تا پیش از تسویه، وضعیتِ پرداخت قابلِ پیگیری و برگشت باشد.': 'Используйте Кошелек → «Безопасный перевод» и введите Earth ID получателя. Этот поток создает доверительный заказ, чтобы можно было отслеживать статус платежа и возвращать его до расчета.',
