    'اینجا هنوز پستی نیست.': 'Здесь пока нет поста.',
    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'Создавая учетную запись, вы соглашаетесь предоставлять точную информацию, не использовать Сервис для незаконной деятельности и нести ответственность за сохранение конфиденциальности ваших учетных данных.',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'Когда начнется трансляция, ваша камера и микрофон будут отправлены зрителям. Если у вас есть еще одно открытое воспроизведение, оно будет закрыто.',
    'با پذیرش، {0} تومان از کیفِ پولِ شما امانی می‌شود و بقیهٔ پیشنهادها رد می‌شوند. این کار برگشت‌پذیر نیست.': 'После принятия {0} томанс будут сняты с вашего кошелька, а остальные предложения будут отклонены. Это необратимо.',
    'با پلاک یا کد ملی، سوابق و سطحِ تخفیف را می‌آوریم.': 'При наличии номерного знака или национального кода мы приводим записи и уровень скидки.',
    'با کد ملی، اطلاعاتِ هویتی را می‌آوریم.': 'Вместе с национальным кодом мы приносим идентификационную информацию.',
