    'Dilix یک بسترِ واسط است و خود ارائه‌دهنده‌ی خدماتِ مالی، بیمه‌ای یا حمل‌ونقلِ دارای مجوز نیست. خدمات از طریقِ شرکای دارای مجوز ارائه می‌شوند و مسئولیتِ صدور و اجرای آن‌ها بر عهده‌ی همان ارائه‌دهنده است.': 'डिलिक्स एक मध्यस्थ मंच है और यह स्वयं वित्तीय, बीमा या परिवहन सेवाओं का लाइसेंस प्राप्त प्रदाता नहीं है। सेवाएँ लाइसेंस प्राप्त भागीदारों के माध्यम से प्रदान की जाती हैं और उनके जारी करने और कार्यान्वयन की जिम्मेदारी उसी प्रदाता की होती है।',
