    'از بخشِ «خدمات» → «اسنپِ بار» → «ثبتِ بار» را انتخاب کنید. مبدأ، مقصد، عنوانِ بار و وزن را وارد کنید. بارِ شما به رانندگانِ در مسیر نمایش داده می‌شود.': 'अनुभाग से "सेवाएँ" → "स्नैप लोड" → "लोड पंजीकरण" चुनें। उत्पत्ति, गंतव्य, कार्गो शीर्षक और वजन दर्ज करें। आपका लोड मार्ग पर ड्राइवरों को प्रदर्शित किया जाएगा।',
    'از کیفِ پول → «انتقالِ امن» استفاده کنید و Earth ID گیرنده را وارد کنید. این جریان سفارشِ امانی می‌سازد تا پیش از تسویه، وضعیتِ پرداخت قابلِ پیگیری و برگشت باشد.': 'वॉलेट → "सुरक्षित स्थानांतरण" का उपयोग करें और प्राप्तकर्ता की अर्थ आईडी दर्ज करें। यह प्रवाह एक ट्रस्ट ऑर्डर बनाता है ताकि भुगतान की स्थिति को ट्रैक किया जा सके और निपटान से पहले वापस किया जा सके।',
