    'اکتشافِ جهانیِ افراد و کسب‌وکارها روی نقشهٔ سه‌بعدی': '3डी मानचित्र पर लोगों और व्यवसायों का वैश्विक अन्वेषण',
    'اکنون در سطحِ منطقه (fuzzed) روی کره دیده می‌شوید.': 'अब आप ग्लोब पर धुंधला क्षेत्र देख सकते हैं।',
    'اگر بار پذیرفته شده باشد، وجهِ امانی کاملاً به شما بازمی‌گردد. پس از تحویل‌گیری دیگر لغو ممکن نیست.': 'यदि लोड स्वीकार कर लिया जाता है, तो जमा राशि आपको पूरी तरह वापस कर दी जाएगी। डिलीवरी के बाद कैंसिलेशन संभव नहीं है.',
    'اگر کسی شما را به دیلیکس دعوت کرده، Earth ID او را ثبت کنید. این کار فقط یک‌بار ممکن است.': 'यदि कोई आपको Dilix पर आमंत्रित करता है, तो उनकी अर्थ आईडी पंजीकृत करें। यह केवल एक बार ही संभव है.',
