    'این پخشِ خودت است؛ از حالتِ میزبان مدیریتش کن.': 'यह आपका अपना प्रसारण है; इसे होस्ट मोड से प्रबंधित करें.',
    'این پروفایلِ خودِ شماست': 'यह आपकी अपनी प्रोफ़ाइल है',
    'این پست برای همیشه حذف می‌شود.': 'यह पोस्ट स्थायी रूप से हटा दी जाएगी.',
    'این پیام برای همه حذف می‌شود. مطمئنی؟': 'यह संदेश सभी के लिए हटा दिया जाएगा. क्या आप निश्चित हैं?',
    'این پیام حذف شد': 'यह संदेश हटाया गया',
    'این کاربر مسدود است؛ ارسالِ پیام ممکن نیست.': 'यह उपयोगकर्ता अवरुद्ध है; संदेश भेजना संभव नहीं है.',
    'این کد را اسکن کنید تا پروفایل باز شود.': 'प्रोफ़ाइल खोलने के लिए इस कोड को स्कैन करें.',
    'اینترنت و eSIM': 'इंटरनेट और eSIM',
    'اینجا هنوز پستی نیست.': 'यहां अभी तक कोई पोस्ट नहीं है.',
    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'एक खाता बनाकर, आप सटीक जानकारी प्रदान करने, अवैध गतिविधि के लिए सेवा का उपयोग न करने और अपने लॉगिन क्रेडेंशियल की गोपनीयता बनाए रखने के लिए जिम्मेदार होने के लिए सहमत हैं।',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'जब प्रसारण शुरू होगा, तो आपका कैमरा और माइक्रोफ़ोन दर्शकों को भेजा जाएगा। यदि आपके पास एक और खुला प्लेबैक है, तो यह बंद हो जाएगा।',
    'با پذیرش، {0} تومان از کیفِ پولِ شما امانی می‌شود و بقیهٔ پیشنهادها رد می‌شوند. این کار برگشت‌پذیر نیست.': 'स्वीकृति पर, {0} टॉमन्स आपके वॉलेट से जमा कर दिए जाएंगे और बाकी ऑफ़र अस्वीकार कर दिए जाएंगे। यह प्रतिवर्ती नहीं है.',
    'با پلاک یا کد ملی، سوابق و سطحِ تخفیف را می‌آوریم.': 'लाइसेंस प्लेट या राष्ट्रीय कोड के साथ, हम रिकॉर्ड और छूट का स्तर लाते हैं।',
    'با کد ملی، اطلاعاتِ هویتی را می‌آوریم.': 'राष्ट्रीय कोड के साथ, हम पहचान की जानकारी लाते हैं।',
