    'Dilix v1.0.0 · ساخته‌شده با ❤️ در ایران': 'Dilix v1.0.0 · hecho con ❤️ en Irán',
    'Dilix یک بسترِ واسط است و خود ارائه‌دهنده‌ی خدماتِ مالی، بیمه‌ای یا حمل‌ونقلِ دارای مجوز نیست. خدمات از طریقِ شرکای دارای مجوز ارائه می‌شوند و مسئولیتِ صدور و اجرای آن‌ها بر عهده‌ی همان ارائه‌دهنده است.': 'Dilix es una plataforma intermediaria y no es en sí misma un proveedor autorizado de servicios financieros, de seguros o de transporte. Los servicios se brindan a través de socios autorizados y la responsabilidad de su emisión e implementación recae en el mismo proveedor.',
