    'از بخشِ «خدمات» → «اسنپِ بار» → «ثبتِ بار» را انتخاب کنید. مبدأ، مقصد، عنوانِ بار و وزن را وارد کنید. بارِ شما به رانندگانِ در مسیر نمایش داده می‌شود.': 'Elija "Servicios" → "Carga instantánea" → "Cargar registro" de la sección. Ingrese origen, destino, título de la carga y peso. Su carga se mostrará a los conductores en la ruta.',
    'از کیفِ پول → «انتقالِ امن» استفاده کنید و Earth ID گیرنده را وارد کنید. این جریان سفارشِ امانی می‌سازد تا پیش از تسویه، وضعیتِ پرداخت قابلِ پیگیری و برگشت باشد.': 'Utilice Wallet → "Transferencia segura" e ingrese el ID de Earth del destinatario. Este flujo crea una orden de confianza para que se pueda rastrear el estado del pago y devolverlo antes de la liquidación.',
