    'اگر کسی شما را به دیلیکس دعوت کرده، Earth ID او را ثبت کنید. این کار فقط یک‌بار ممکن است.': 'Si alguien te invita a Dilix, registra su ID de Earth. Esto sólo es posible una vez.',
