    'اینجا هنوز پستی نیست.': 'No hay ninguna publicación aquí todavía.',
    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'Al crear una cuenta, usted acepta proporcionar información precisa, no utilizar el Servicio para actividades ilegales y ser responsable de mantener la confidencialidad de sus credenciales de inicio de sesión.',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'Cuando comience la transmisión, su cámara y micrófono se enviarán a los espectadores. Si tienes otra reproducción abierta, se cerrará.',
    'با پذیرش، {0} تومان از کیفِ پولِ شما امانی می‌شود و بقیهٔ پیشنهادها رد می‌شوند. این کار برگشت‌پذیر نیست.': 'Tras la aceptación, se depositarán {0} Tomans desde su billetera y el resto de las ofertas serán rechazadas. Esto no es reversible.',
    'با پلاک یا کد ملی، سوابق و سطحِ تخفیف را می‌آوریم.': 'Con matrícula o código nacional, traemos registros y nivel de descuento.',
