    'از بخشِ «خدمات» → «اسنپِ بار» → «ثبتِ بار» را انتخاب کنید. مبدأ، مقصد، عنوانِ بار و وزن را وارد کنید. بارِ شما به رانندگانِ در مسیر نمایش داده می‌شود.': 'Choisissez « Services » → « Snap Load » → « Load Registration » dans la section. Entrez l\'origine, la destination, le titre de la cargaison et le poids. Votre chargement sera affiché aux chauffeurs sur le parcours.',
    'از کیفِ پول → «انتقالِ امن» استفاده کنید و Earth ID گیرنده را وارد کنید. این جریان سفارشِ امانی می‌سازد تا پیش از تسویه، وضعیتِ پرداخت قابلِ پیگیری و برگشت باشد.': 'Utilisez Wallet → « Transfert sécurisé » et saisissez l\'identifiant Earth du destinataire. Ce flux crée un ordre de confiance afin que le statut du paiement puisse être suivi et renvoyé avant le règlement.',
