    'اگر بار پذیرفته شده باشد، وجهِ امانی کاملاً به شما بازمی‌گردد. پس از تحویل‌گیری دیگر لغو ممکن نیست.': 'Si le chargement est accepté, la caution vous sera intégralement restituée. L\'annulation n\'est pas possible après la livraison.',
