    'اینجا هنوز پستی نیست.': 'Il n\'y a pas encore de message ici.',
    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'En créant un compte, vous acceptez de fournir des informations exactes, de ne pas utiliser le Service à des fins d\'activités illégales et d\'être responsable du maintien de la confidentialité de vos identifiants de connexion.',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'Lorsque la diffusion démarre, votre caméra et votre microphone seront envoyés aux téléspectateurs. Si vous avez une autre lecture ouverte, elle sera fermée.',
