    'از': 'Von',
    'از بخشِ «خدمات» → «اسنپِ بار» → «ثبتِ بار» را انتخاب کنید. مبدأ، مقصد، عنوانِ بار و وزن را وارد کنید. بارِ شما به رانندگانِ در مسیر نمایش داده می‌شود.': 'Wählen Sie im Abschnitt „Dienste“ → „Snap Load“ → „Registrierung laden“. Geben Sie Herkunft, Ziel, Frachttitel und Gewicht ein. Ihre Ladung wird den Fahrern auf der Route angezeigt.',
    'از کیفِ پول → «انتقالِ امن» استفاده کنید و Earth ID گیرنده را وارد کنید. این جریان سفارشِ امانی می‌سازد تا پیش از تسویه، وضعیتِ پرداخت قابلِ پیگیری و برگشت باشد.': 'Verwenden Sie Wallet → „Sichere Übertragung“ und geben Sie die Earth-ID des Empfängers ein. Dieser Ablauf erstellt einen Treuhandauftrag, sodass der Zahlungsstatus verfolgt und vor der Abrechnung zurückgegeben werden kann.',
