    'اکنون در سطحِ منطقه (fuzzed) روی کره دیده می‌شوید.': 'Jetzt können Sie den unscharfen Bereich auf dem Globus sehen.',
    'اگر بار پذیرفته شده باشد، وجهِ امانی کاملاً به شما بازمی‌گردد. پس از تحویل‌گیری دیگر لغو ممکن نیست.': 'Bei Annahme der Ladung wird Ihnen die Kaution vollständig zurückerstattet. Eine Stornierung nach Lieferung ist nicht möglich.',
