    'اینجا هنوز پستی نیست.': 'Hier gibt es noch keinen Beitrag.',
    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'Durch die Erstellung eines Kontos erklären Sie sich damit einverstanden, korrekte Informationen anzugeben, den Dienst nicht für illegale Aktivitäten zu nutzen und für die Wahrung der Vertraulichkeit Ihrer Anmeldedaten verantwortlich zu sein.',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'Wenn die Übertragung beginnt, werden Ihre Kamera und Ihr Mikrofon an die Zuschauer gesendet. Wenn Sie eine weitere offene Wiedergabe haben, wird diese geschlossen.',
    'با پذیرش، {0} تومان از کیفِ پولِ شما امانی می‌شود و بقیهٔ پیشنهادها رد می‌شوند. این کار برگشت‌پذیر نیست.': 'Bei Annahme werden {0} Tomans von Ihrem Guthaben abgebucht und die restlichen Angebote werden abgelehnt. Dies ist nicht umkehrbar.',
    'با پلاک یا کد ملی، سوابق و سطحِ تخفیف را می‌آوریم.': 'Mit Nummernschild oder Ländercode bringen wir Aufzeichnungen und die Höhe des Rabatts.',
    'با کد ملی، اطلاعاتِ هویتی را می‌آوریم.': 'Mit dem Landescode bringen wir die Identitätsinformationen.',
