    'از': 'من',
    'از بخشِ «خدمات» → «اسنپِ بار» → «ثبتِ بار» را انتخاب کنید. مبدأ، مقصد، عنوانِ بار و وزن را وارد کنید. بارِ شما به رانندگانِ در مسیر نمایش داده می‌شود.': 'اختر "الخدمات" ← "تحميل سريع" ← "تسجيل التحميل" من القسم. أدخل الأصل والوجهة وعنوان الشحنة والوزن. سيتم عرض حمولتك للسائقين على الطريق.',
    'از کیفِ پول → «انتقالِ امن» استفاده کنید و Earth ID گیرنده را وارد کنید. این جریان سفارشِ امانی می‌سازد تا پیش از تسویه، وضعیتِ پرداخت قابلِ پیگیری و برگشت باشد.': 'استخدم Wallet → "النقل الآمن" وأدخل معرف Earth الخاص بالمستلم. يقوم هذا التدفق بإنشاء أمر ثقة بحيث يمكن تتبع حالة الدفع وإرجاعها قبل التسوية.',
