    'اکتشافِ جهانیِ افراد و کسب‌وکارها روی نقشهٔ سه‌بعدی': 'استكشاف عالمي للأشخاص والشركات على خريطة ثلاثية الأبعاد',
    'اکنون در سطحِ منطقه (fuzzed) روی کره دیده می‌شوید.': 'الآن يمكنك رؤية المنطقة الغامضة على الكرة الأرضية.',
    'اگر بار پذیرفته شده باشد، وجهِ امانی کاملاً به شما بازمی‌گردد. پس از تحویل‌گیری دیگر لغو ممکن نیست.': 'إذا تم قبول الحمولة، فسيتم إرجاع الوديعة إليك بالكامل. لا يمكن الإلغاء بعد التسليم.',
    'اگر کسی شما را به دیلیکس دعوت کرده، Earth ID او را ثبت کنید. این کار فقط یک‌بار ممکن است.': 'إذا دعاك شخص ما إلى Dilix، فقم بتسجيل معرف Earth الخاص به. وهذا ممكن مرة واحدة فقط.',
