    'این کاربر مسدود است؛ ارسالِ پیام ممکن نیست.': 'هذا المستخدم محظور؛ ليس من الممكن إرسال رسالة.',
    'این کد را اسکن کنید تا پروفایل باز شود.': 'قم بمسح هذا الرمز ضوئيًا لفتح الملف الشخصي.',
    'اینترنت و eSIM': 'الإنترنت والشريحة الإلكترونية eSIM',
    'اینجا هنوز پستی نیست.': 'لا يوجد أي وظيفة هنا حتى الآن.',
    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'من خلال إنشاء حساب، فإنك توافق على تقديم معلومات دقيقة، وعدم استخدام الخدمة في نشاط غير قانوني، وتكون مسؤولاً عن الحفاظ على سرية بيانات اعتماد تسجيل الدخول الخاصة بك.',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'عندما يبدأ البث، سيتم إرسال الكاميرا والميكروفون إلى المشاهدين. إذا كان لديك تشغيل مفتوح آخر، فسيتم إغلاقه.',
    'با پذیرش، {0} تومان از کیفِ پولِ شما امانی می‌شود و بقیهٔ پیشنهادها رد می‌شوند. این کار برگشت‌پذیر نیست.': 'عند القبول، سيتم إيداع {0} تومان من محفظتك وسيتم رفض بقية العروض. هذا لا يمكن عكسه.',
