    'اکنون در سطحِ منطقه (fuzzed) روی کره دیده می‌شوید.': 'اب آپ دنیا پر دھندلا ہوا علاقہ دیکھ سکتے ہیں۔',
    'اگر بار پذیرفته شده باشد، وجهِ امانی کاملاً به شما بازمی‌گردد. پس از تحویل‌گیری دیگر لغو ممکن نیست.': 'اگر بوجھ قبول کر لیا جاتا ہے، تو ڈپازٹ مکمل طور پر آپ کو واپس کر دیا جائے گا۔ ترسیل کے بعد منسوخی ممکن نہیں ہے۔',
    'اگر کسی شما را به دیلیکس دعوت کرده، Earth ID او را ثبت کنید. این کار فقط یک‌بار ممکن است.': 'اگر کوئی آپ کو Dilix پر مدعو کرتا ہے، تو اپنی ارتھ آئی ڈی رجسٹر کریں۔ یہ صرف ایک بار ممکن ہے۔',
