    'با ساختِ حساب، شما می‌پذیرید که اطلاعاتِ صحیح ارائه دهید، از سرویس برای فعالیتِ غیرقانونی استفاده نکنید و مسئولِ حفظِ محرمانگیِ اعتبارنامه‌های ورودِ خود باشید.': 'ایک اکاؤنٹ بنا کر، آپ درست معلومات فراہم کرنے، سروس کو غیر قانونی سرگرمی کے لیے استعمال نہ کرنے، اور اپنے لاگ ان کی اسناد کی رازداری کو برقرار رکھنے کے لیے ذمہ دار ہونے سے اتفاق کرتے ہیں۔',
    'با شروعِ پخش، دوربین و میکروفنِ شما برای بینندگان ارسال می‌شود. اگر پخشِ بازِ دیگری داشته باشید، بسته می‌شود.': 'نشریات شروع ہونے پر، آپ کا کیمرہ اور مائیکروفون ناظرین کو بھیج دیا جائے گا۔ اگر آپ کے پاس دوسرا کھلا پلے بیک ہے، تو اسے بند کر دیا جائے گا۔',
    'با پذیرش، {0} تومان از کیفِ پولِ شما امانی می‌شود و بقیهٔ پیشنهادها رد می‌شوند. این کار برگشت‌پذیر نیست.': 'قبول ہونے پر، {0} ٹومنز آپ کے بٹوے سے جمع کر دیے جائیں گے اور باقی پیشکشیں مسترد کر دی جائیں گی۔ یہ الٹنے والا نہیں ہے۔',
    'با پلاک یا کد ملی، سوابق و سطحِ تخفیف را می‌آوریم.': 'لائسنس پلیٹ یا قومی کوڈ کے ساتھ، ہم ریکارڈ اور رعایت کی سطح لاتے ہیں۔',
    'با کد ملی، اطلاعاتِ هویتی را می‌آوریم.': 'قومی کوڈ کے ساتھ، ہم شناخت کی معلومات لاتے ہیں۔',
